const logo=()=>`<a class="brand" href="index.html" aria-label="Desert Rover Hurghada home"><svg class="brand-mountain" viewBox="0 0 118 44" fill="none" aria-hidden="true"><path d="M2 36 25 20l13 8L56 4l19 22 12-11 29 21" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="m39 26 17-22 10 15m5 10 17-14 15 17" stroke="currentColor" stroke-width="2"/><path d="M16 42h89" stroke="currentColor" stroke-width="1.7"/></svg><span><strong>DESERT ROVER</strong><small>H U R G H A D A</small></span></a>`;
function navLink(k){return `<a class="nav-link ${page===({experiences:'experiences',privateTours:'private',families:'families',story:'about',reviews:'reviews',faq:'faq',contact:'contact'}[k]||'home')?'active':''}" href="${links[k]}">${t(k)}</a>`}
function header(){return `<div class="site-loader" id="loader" role="status" aria-live="polite"><div class="loader-core"><svg viewBox="0 0 130 60" aria-hidden="true"><path d="m5 47 24-19 13 7L65 9l21 27 15-14 24 25" fill="none" stroke="#d5ae69" stroke-width="3"/></svg><strong>DESERT ROVER</strong><span>HURGHADA</span><div class="loader-track"><i></i></div><small>DISCOVER THE EXTRAORDINARY</small></div></div><div class="announcement"><span>${icon('sparkles')} ${lang==='de'?'ENTDECKE HURGHADA MIT UNS':lang==='ar'?'اكتشف مغامرات الغردقة':'A WORLD OF ADVENTURE IN HURGHADA'}</span><span class="announcement-right">${t('location')}</span></div><header class="site-header" id="site-header"><div class="header-inner container">${logo()}<nav class="desktop-nav" aria-label="Main navigation">${['experiences','privateTours','families','story','reviews','faq','contact'].map(navLink).join('')}</nav><div class="header-actions"><div class="lang-switch" role="group" aria-label="${t('language')}">${['en','de','ar'].map(l=>`<button type="button" class="lang-btn ${l===lang?'selected':''}" data-lang="${l}" aria-label="${l.toUpperCase()}" aria-pressed="${l===lang}">${l.toUpperCase()}</button>`).join('')}</div><a href="my-bookings.html" class="icon-btn desktop-only" aria-label="${t('myBookings')}">${icon('bookmark')}</a><a class="btn btn-gold btn-small desktop-only" href="experiences.html">${icon('calendar-days')}${t('bookNow')}</a><button class="menu-toggle" id="menu-toggle" aria-label="Open menu" aria-expanded="false">${icon('menu')}</button></div></div><div class="mobile-menu" id="mobile-menu"><nav aria-label="Mobile navigation">${['home','experiences','privateTours','families','story','reviews','faq','contact'].map(navLink).join('')}<a href="my-bookings.html" class="nav-link">${t('myBookings')}</a></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div class="footer-about">${logo()}<p>${t('footerText')}</p><div class="footer-social"><span aria-label="Instagram">${icon('instagram')}</span><span aria-label="Facebook">${icon('facebook')}</span><span aria-label="Youtube">${icon('youtube')}</span></div></div><div><h4>${t('exploreLabel')}</h4>${['experiences','privateTours','families','story'].map(k=>`<a href="${links[k]}">${t(k)}</a>`).join('')}</div><div><h4>${t('support')}</h4>${['faq','reviews','contact'].map(k=>`<a href="${links[k]}">${t(k)}</a>`).join('')}<a href="my-bookings.html">${t('myBookings')}</a></div><div><h4>${t('keepTouch')}</h4><p>${icon('map-pin')} ${t('location')}</p><p class="preview-contacts">${lang==='ar'?'أضف بيانات التواصل الرسمية للعميل':lang==='de'?'Offizielle Kontaktdaten ergänzen':'Add the operator’s verified contact details'}</p><a href="contact.html" class="footer-help">${t('contact')} ${icon('arrow-up-right')}</a></div></div><div class="footer-bottom"><span>${t('copyright')}</span><span class="preview-small">${t('previewNote')}</span><button type="button" class="back-top" id="back-top">${t('top')} ${icon('arrow-up')}</button></div></div></footer><div id="toast" class="toast" role="status" aria-live="polite"></div><div class="lightbox" id="lightbox" aria-hidden="true"><button aria-label="Close" class="lightbox-close">${icon('x')}</button><img alt="Expanded experience photograph" src=""/></div>`}
const img=(name,alt='',cls='',eager=true)=>`<img src="${asset(name)}" alt="${esc(alt)}" class="${cls}" loading="${eager?'eager':'lazy'}" decoding="async"/>`;
function sectionTitle(k,headline,copy='',center=false){return `<div class="section-heading reveal ${center?'text-center':''}"><div class="eyebrow ornament">${t(k)}</div><h2 class="serif">${headline}</h2>${copy?`<p>${copy}</p>`:''}</div>`}
function categories(){const cats=[['horse','horse','sea-riders'],['camel','camel','camel-gold'],['sea','sea','horse-coast'],['desert','desert','beach-desert']];const names={en:['Sea horse riding','Camel adventures','Beach & coast rides','Desert exploration'],de:['Reiten im Meer','Kamel-Abenteuer','Ausritte an der Küste','Wüste entdecken'],ar:['ركوب الخيل في البحر','مغامرات الجمال','ركوب الخيل على الشاطئ','استكشاف الصحراء']};return `<div class="category-grid">${cats.map((c,i)=>`<a class="category-card reveal" href="experiences.html?category=${c[0]}">${img(c[2],names[lang][i])}<span class="category-shade"></span><span class="category-copy"><strong class="serif">${names[lang][i]}</strong><span>${t('exploreLabel')} ${icon('arrow-up-right')}</span></span></a>`).join('')}</div>`}
function trustBand(){return `<div class="trust-band"><div class="container trust-items">${[['gem','personal','personalCopy'],['users-round','allAges','familyCopy'],['shield-check','secure','secureCopy'],['map-pin','location','localsCopy']].map(x=>`<div class="trust-item">${icon(x[0])}<span><strong>${t(x[1])}</strong><small>${t(x[2])}</small></span></div>`).join('')}</div></div>`}
