function reviewSection(){return `<section class="section reviews-section soft" id="reviews"><div class="container">${sectionTitle('feedback',''+t('feedbackTitle'),t('feedbackNote'),true)}<div class="review-layout"><button class="round-nav" id="review-prev" aria-label="${t('prev')}">${icon('arrow-left')}</button><div class="review-grid" id="review-grid">${sampleReviews.map(r=>`<div class="review-card reveal"><div class="review-top">${img(r.photo,'Sample review layout')}<span class="stars" aria-label="Example five stars">★★★★★</span></div><blockquote>“${r[lang]||r.en}”</blockquote><small>${t('reviewSample')}</small></div>`).join('')}</div><button class="round-nav" id="review-next" aria-label="${t('next')}">${icon('arrow-right')}</button></div></div></section>`}
